  {accessorKey: 'city', header: 'Город', size: 150},
  {accessorKey: 'createdAt', header: 'Дата', size: 130},
  {accessorKey: 'itemsCount', header: 'Позиций', size: 100},
  {accessorKey: 'total', header: 'Сумма', size: 140, cell: ...},
  {accessorKey: 'status', header: 'Статус', size: 140, cell: info => {const item = info.row.original; return 'status' in item ? <Label theme=...>{label}</Label> : null}},
];
```

