export function OrdersTable() {
  const data = React.useMemo(() => buildGroupedOrders(), []);
  const [expanded, setExpanded] = React.useState<ExpandedState>(true);
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({});

  const getSubRows = React.useCallback((item: OrderTableItem) => (isStatusGroup(item) ? item.items : undefined), []);
  const getRowId = React.useCallback((item: OrderTableItem) => item.id, []);

  const handleRowSelectionChange = useRowSelectionFixedHandler({
    rowSelection,
    setRowSelection,
    tableData: data,
    getSubRows,
    getRowId,
  });

  const table = useTable({
    columns,
    data,
    enableExpanding: true,
    enableRowSelection: true,
    enableMultiRowSelection: true,
    getRowId,
    getSubRows,
    onExpandedChange: setExpanded,
    onRowSelectionChange: handleRowSelectionChange,
    state: {expanded, rowSelection},
  });

  const selectedCount = Object.keys(rowSelection).length;

  return (
    <ColumnReorderingProvider table={table}>
      <Flex direction="column" gap={3}>
        <Flex alignItems="center" gap={3} style={{minHeight: 28}}>
          <Text variant="body-2" color="secondary" style={{flex: 1, minWidth: 0}}>
            {selectedCount > 0 ? `Выбрано заказов: ${selectedCount}` : 'Строки можно выделять, колонки — перетаскивать за заголовок'}
          </Text>
          {selectedCount > 0 && (
            <Button view="flat" size="m" onClick={() => setRowSelection({})} style={{flexShrink: 0}}>Снять выделение</Button>
          )}
        </Flex>
        <Table
          table={table}
          getIsGroupHeaderRow={getIsGroupHeaderRow}
          getGroupTitle={getGroupTitle}
          onRowClick={handleRowClick}
        />
      </Flex>
    </ColumnReorderingProvider>
  );
}
```

